/** A route of the manifest generated by the renderer (`src/.cormi/routes.*`). */
export interface RouteData {
  id: string
  path?: string
  index?: boolean
  parentId?: string
  /** the route module exports `loader`, which runs on the server */
  hasLoader?: boolean
  /** the route module exports `clientLoader`, which runs in the browser */
  hasClientLoader?: boolean
  /** a layout wrapping other routes */
  isLayout?: boolean
  /** static data of the route, e.g. `name` and `icon` for menus */
  meta?: Record<string, any>
}

/** Exports of a route module; what the component is depends on the UI framework. */
export interface RouteModule {
  default?: unknown
  /** runs on the server; removed from the client bundle */
  loader?: (...args: any[]) => unknown
  /** runs in the browser */
  clientLoader?: (...args: any[]) => unknown
  [key: string]: unknown
}

export type RouteModules<M = RouteModule> = Record<string, () => Promise<M>>

export type HistoryType = 'browser' | 'hash' | 'memory'

/** Where the app is: the parts of a URL below the origin. */
export interface Location {
  pathname: string
  search: string
  hash: string
  state?: unknown
  key?: string
}

/** How a location was reached. */
export type NavigationType = 'POP' | 'PUSH' | 'REPLACE'

declare global {
  interface Window {
    /** hydration data written during server rendering */
    __staticRouterHydrationData?: any
  }
}
